static int parse_input(const char *line, int *stones, int *n, int *k) {
    const char *p = line;
    while (*p && *p != '[') p++;
    if (!*p) return 0;
    p++;
    while (*p && *p != '[') p++;
    if (!*p) return 0;
    p++;

    *n = 0;
    while (*p && *p != ']') {
        if (*p >= '0' && *p <= '9') {
            char *endptr;
            long v = strtol(p, &endptr, 10);
            stones[(*n)++] = (int)v;
            p = endptr;
        } else {
            p++;
        }
    }
    if (*p != ']') return 0;
    p++;

    while (*p && (*p < '0' || *p > '9')) p++;
    if (!*p) return 0;
    *k = atoi(p);
    return 1;
}

int mergeStones(int *stones, int stonesSize, int k) {
    if (stonesSize == 1) return 0;
    if ((stonesSize - 1) % (k - 1) != 0) return -1;

    long long prefix[31] = {0};
    for (int i = 0; i < stonesSize; ++i) {
        prefix[i + 1] = prefix[i] + stones[i];
    }

    const long long INF = (1LL << 60);
    long long dp[30][30] = {{0}};

    for (int len = k; len <= stonesSize; ++len) {
        int span = len - 1;
        for (int i = 0; i + len <= stonesSize; ++i) {
            int j = i + span;
            long long best = INF;
            for (int m = i; m < j; m += k - 1) {
                long long candidate = dp[i][m] + dp[m + 1][j];
                if (candidate < best) best = candidate;
            }
            dp[i][j] = best;
            if ((len - 1) % (k - 1) == 0) {
                dp[i][j] += prefix[j + 1] - prefix[i];
            }
        }
    }

    return (int)dp[0][stonesSize - 1];
}

