import java.io.*;
import java.util.*;

class Solution {
    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if (n == 1) return 0;
        if ((n - 1) % (k - 1) != 0) return -1;

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n][n];

        for (int length = k; length <= n; length++) {
            int span = length - 1;
            for (int i = 0; i + length <= n; i++) {
                int j = i + span;
                long best = INF;
                for (int m = i; m < j; m += k - 1) {
                    best = Math.min(best, dp[i][m] + dp[m + 1][j]);
                }
                dp[i][j] = best;
                if ((length - 1) % (k - 1) == 0) {
                    dp[i][j] += prefix[j + 1] - prefix[i];
                }
            }
        }

        return (int) dp[0][n - 1];
    }
}

public class Main {
    static int[] parseStones(String line) {
        int start = line.indexOf('[', 1) + 1;
        int end = line.indexOf(']', start);
        if (end < 0) throw new IllegalArgumentException("Invalid input");
        String body = line.substring(start, end).trim();
        if (body.isEmpty()) return new int[0];

        String[] parts = body.split(",");
        int[] stones = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            stones[i] = Integer.parseInt(parts[i].trim());
        }
        return stones;
    }

    static int parseK(String line) {
        int end = line.indexOf(']', line.indexOf('[', 1) + 1);
        String tail = line.substring(end + 1).replaceAll("[^0-9-]", "");
        return Integer.parseInt(tail);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[] stones = parseStones(line);
        int k = parseK(line);
        System.out.println(new Solution().mergeStones(stones, k));
    }
}

